{
  "status": "needs_input",
  "message": "어떤 Slack 알림이 '중요한' 알림인지 기준을 알려주세요. 예를 들어, 특정 사람, 채널, 키워드, 멘션 등 구체적인 조건이 있다면 선택해 주세요.",
  "questions": [
    {
      "id": "meaning-important",
      "field": "meaning",
      "kind": "multiple",
      "prompt": "'중요한' Slack 알림의 기준을 선택해 주세요.",
      "reason": "‘중요’의 기준이 주관적이어서, 어떤 알림을 받고 싶은지 구체적으로 확인이 필요합니다.",
      "options": [
        {
          "id": "mention",
          "label": "나를 멘션한 알림만",
          "candidate_id": null
        },
        {
          "id": "direct-message",
          "label": "나에게 온 다이렉트 메시지만",
          "candidate_id": null
        },
        {
          "id": "specific-channel",
          "label": "특정 채널(채널명을 입력해 주세요)",
          "candidate_id": null
        },
        {
          "id": "specific-person",
          "label": "특정 사람(이름을 입력해 주세요)",
          "candidate_id": null
        },
        {
          "id": "custom-keyword",
          "label": "특정 키워드가 포함된 알림(키워드를 입력해 주세요)",
          "candidate_id": null
        }
      ]
    }
  ],
  "unresolved": [
    "‘중요한’ Slack 알림의 구체적인 기준"
  ],
  "normalized_instruction": null,
  "referenced_candidate_ids": [],
  "change_kind": "new",
  "change_summary": "Slack에서 '중요한' 알림만 받도록 요청하였으나, '중요'의 기준이 명확하지 않아 추가 정보가 필요함."
}
